Object.assign(BIZSUF,{sportschool:['Gym','Fit','Sportcentrum'],kinderopvang:['Kids','Kinderhuis','Speelhuis'],garage:['Garage','Autoservice','Motors'],makelaar:['Makelaars','Wonen','Vastgoed'],platenlabel:['Records','Music','Sound'],nachtclub:['Club','Nights','Lounge'],bakkerij:['Bakkerij','Bakery','Brood'],schoonmaak:['Schoonmaak','Clean','Service'],uitzend:['Uitzend','Werk','Talent'],kleding:['Wear','Apparel','Studio'],brouwerij:['Brouwerij','Brewing','Bier'],escape:['Escape','Mysteries','Rooms']});
const BIZGRP=[['🍽️ Eten en drinken',['foodtruck','bakkerij','cafe','restaurant','brouwerij','nachtclub','hotel']],['🛠️ Diensten',['schoonmaak','kapsalon','escape','sportschool','garage','kinderopvang','bouwbedrijf']],['💼 Zakelijk',['consultancy','makelaar','uitzend']],['💻 Online en creatief',['webshop','kleding','platenlabel','saas','app']]];
const ONLINE=['webshop','saas','app','consultancy','platenlabel','kleding'];
const FRANCH=['foodtruck','restaurant','cafe','kapsalon','sportschool','kinderopvang','bakkerij','schoonmaak','escape','garage','makelaar','bouwbedrijf'];
const FOODT=['foodtruck','restaurant','cafe','bakkerij','brouwerij','nachtclub','hotel'];
const NLCITY=['Amsterdam','Rotterdam','Den Haag','Utrecht','Eindhoven','Groningen','Tilburg','Breda','Nijmegen','Maastricht','Zwolle','Haarlem','Arnhem','Leiden','Den Bosch','Almere','Enschede','Delft','Leeuwarden','Amersfoort'];
const BIZLAND=['België','Duitsland','Frankrijk','het Verenigd Koninkrijk','Spanje','Italië','Scandinavië','de Verenigde Staten','Japan','Brazilië','Australië','Canada','Ierland','Portugal','Oostenrijk','Zwitserland','Polen','Tsjechië','Griekenland','Turkije','Marokko','Zuid-Afrika','Nigeria','Egypte','de Verenigde Arabische Emiraten','Saoedi-Arabië','India','China','Zuid-Korea','Singapore','Indonesië','Thailand','Vietnam','de Filipijnen','Nieuw-Zeeland','Mexico','Argentinië','Chili','Colombia','Peru'];
const EMPF={foodtruck:['Kok','Verkoper'],restaurant:['Kok','Sous-chef','Bediening','Afwasser','Gastheer'],cafe:['Barman','Bediening','Kok'],webshop:['Orderpicker','Klantenservice','Marketeer'],saas:['Developer','Designer','Sales','Support'],bouwbedrijf:['Timmerman','Metselaar','Uitvoerder','Loodgieter'],kapsalon:['Kapper','Stylist'],consultancy:['Consultant','Analist'],hotel:['Receptionist','Housekeeping','Kok','Bediening','Nachtportier'],app:['Developer','Designer','Marketeer'],sportschool:['Personal trainer','Baliemedewerker','Instructeur'],kinderopvang:['Pedagogisch medewerker','Groepsleider'],garage:['Monteur','APK-keurmeester','Baliemedewerker'],makelaar:['Makelaar','Taxateur','Binnendienst'],platenlabel:['A&R-manager','Producer','Promotor'],nachtclub:['Barman','Portier','DJ','Bediening'],bakkerij:['Bakker','Verkoper'],schoonmaak:['Schoonmaker','Teamleider'],uitzend:['Intercedent','Accountmanager'],kleding:['Ontwerper','Inkoper','Webshopmedewerker'],brouwerij:['Brouwer','Bottelaar','Verkoper'],escape:['Gamemaster','Puzzelontwerper']};
// eigenschap: [naam, effect op werk, effect op humeur per jaar]
const ETRAITS={'harde werker':[8,0],'lui':[-10,2],'gezellig':[0,4],'ambitieus':[4,-2],'onbetrouwbaar':[-4,0],'loyaal':[2,3],'perfectionist':[6,-1],'grappig':[0,3]};
const EMPMAX=15;
// omzetplafond per vestiging (of per markt bij online bedrijven) bij een goede reputatie, en wat een nieuwe vestiging kost om te openen
const PEAK={foodtruck:150000,restaurant:900000,cafe:600000,webshop:2000000,saas:3000000,bouwbedrijf:3000000,kapsalon:300000,consultancy:1500000,hotel:3000000,app:4000000,sportschool:600000,kinderopvang:1200000,garage:900000,makelaar:800000,platenlabel:3000000,nachtclub:2500000,bakkerij:500000,schoonmaak:1500000,uitzend:5000000,kleding:4000000,brouwerij:2000000,escape:350000};
const OPEN={foodtruck:60000,restaurant:350000,cafe:250000,webshop:50000,saas:300000,bouwbedrijf:150000,kapsalon:80000,consultancy:100000,hotel:4000000,app:300000,sportschool:400000,kinderopvang:300000,garage:250000,makelaar:60000,platenlabel:150000,nachtclub:800000,bakkerij:200000,schoonmaak:30000,uitzend:80000,kleding:200000,brouwerij:500000,escape:120000};
// overige kosten als deel van de omzet: energie, verzekering, onderhoud, software, reclame
const OPEX={foodtruck:.15,restaurant:.18,cafe:.18,webshop:.2,saas:.35,bouwbedrijf:.12,kapsalon:.15,consultancy:.15,hotel:.2,app:.38,sportschool:.18,kinderopvang:.12,garage:.12,makelaar:.15,platenlabel:.25,nachtclub:.2,bakkerij:.15,schoonmaak:.1,uitzend:.06,kleding:.22,brouwerij:.18,escape:.18};
// prijsniveau: [naam, icoon, prijs, klanten, uitleg]
const PRL=[['Goedkoop','🏷️',.88,1.35,'Meer klanten, minder marge',1.15],['Normaal','⚖️',1,1,'Gewone prijzen',1],['Premium','💎',1.3,.72,'Minder klanten, veel meer marge. Vraagt om goede kwaliteit',.85]];
// kwaliteit van inkoop en product: [naam, icoon, kosten, reputatie per jaar, groei]
const QLL=[['Budget','📦',.8,-1,-.01,'Goedkope inkoop, klanten merken het'],['Normaal','👍',1,0,0,'Prima kwaliteit'],['Topkwaliteit','⭐',1.25,2,.02,'Duurder, maar klanten komen terug']];
// locatie per vestiging: [naam, icoon, klanten, huur, openingskosten]
const LOCT={A:['A-locatie','🌟',1.35,1.8,1.3,'Druk winkelgebied, dure huur'],B:['B-locatie','🏬',1,1,1,'Gewone straat'],C:['C-locatie','🏚️',.72,.6,.8,'Buitenwijk, goedkoop']};
const prOf=b=>b.pr??(b.price>1.15?2:b.price<.9?0:1),qlOf=b=>b.ql??1;
function setPr(b,d){b.pr=clamp(prOf(b)+d,0,2)/1|0;b.pr=Math.max(0,Math.min(2,b.pr));b.price=PRL[b.pr][2]}
const ramp=a=>Math.min(1,.35+.3*Math.max(0,a));
const canni=(b,i)=>ONLINE.includes(b.type)?1/(1+i/12):1/(1+i/40)*(i>=20?.85:1);
const peakOf=b=>(PEAK[b.type]||BIZ[b.type].rev0*3)*cpi_()*(.6+clamp(b.rep)/175)*PRL[prOf(b)][3];
function bizLo(b){if(!b.lo||b.lo.length!==b.loc){const lo=b.lo||[];while(lo.length<b.loc)lo.push(year()-5);lo.length=b.loc;b.lo=lo}if(!b.la||b.la.length!==b.loc){const la=b.la||[];while(la.length<b.loc)la.push('B');la.length=b.loc;b.la=la}return b.lo}
const rentSum=b=>{bizLo(b);let s=0;for(const t of b.la)s+=LOCT[t][3];return s};
function demandCap(b){const lo=bizLo(b),y=year(),pk=peakOf(b);let s=0;for(let i=0;i<lo.length;i++)s+=ramp(y-lo[i])*canni(b,i)*LOCT[b.la[i]][2];return Math.round(pk*s)}
// hoofdkantoor en regiomanagers: groot zijn kost geld
function overheadPct(b){if(b.loc<5)return 0;const mg=bizMgr(b);const sk_=(S.sk.zaken+(mg?effSk(mg):40))/2;return .022*Math.log2(b.loc/4)*(1.25-sk_/200)}
function vpb(w){if(typeof noTax==='function'&&noTax())return 0;const g=200000*cpi_();const v=law('vpb');return w<=0?0:Math.round(Math.min(w,g)*v*.736+Math.max(0,w-g)*v)}
// oude bedrijven omzetten naar de nieuwe regels
function bizV2(b){if(b.v2)return;b.v2=1;ensureEmp(b);bizLo(b);const T=BIZ[b.type];const D=demandCap(b);if(b.demand>D){b.demand=D;const need=Math.ceil(D/(T.cap*cpi_()))+1;if(b.staff>need*1.3){const cut=b.staff-Math.round(need*1.2);b.staff-=cut;if(b.emp.length>b.staff)b.emp=b.emp.slice(0,b.staff);L(`${b.name}: de markt is verzadigd. ${cut} medewerkers zijn overbodig en vertrekken.`,'bad')}}b.dmax=D}
const cpi_=()=>S.cpi||1;
function mkEmp(b,o={}){const T=BIZ[b.type];const p=mkPerson('medewerker',pick(['m','v']),S.m-ri(18,58)*12-ri(0,11),{rel:ri(45,70)});
  p.fn=o.fn||pick(EMPF[b.type]||['Medewerker']);p.esk=o.esk??ri(20,88);p.tr=o.tr||pick(Object.keys(ETRAITS));p.mood=ri(55,80);p.yrs=0;p.bid=b.id;
  p.wage=Math.round(T.wage*cpi_()*(.75+p.esk/200)*(.9+R()*.2)/100)*100;return p}
const STAFFMAX=200;const nfS=n=>Math.round(n).toLocaleString('nl-NL');const staffCap=b=>STAFFMAX*Math.max(1,b.loc||1);const staffRoom=b=>Math.max(0,staffCap(b)-b.staff);
function ensureEmp(b){if(!b.emp)b.emp=[];if(!b.loc)b.loc=1;if(b.loc>2500&&!ONLINE.includes(b.type))b.loc=2500;if(!b.locs)b.locs=[];if(!(b.staff<=staffCap(b))){b.staff=staffCap(b)}if(b.emp.length>b.staff)b.emp=b.emp.slice(0,b.staff);b.emp=b.emp.filter(p=>p.alive!==false);if(b.staff<b.emp.length)b.staff=b.emp.length;while(b.emp.length<Math.min(b.staff,EMPMAX))b.emp.push(mkEmp(b));return b.emp}
const anonN=b=>Math.max(0,b.staff-(b.emp||[]).length);
const effSk=p=>clamp(p.esk+(ETRAITS[p.tr]||[0])[0]);
const empQ=b=>{const e=ensureEmp(b);return e.length?Math.round(e.reduce((s,p)=>s+effSk(p),0)/e.length):50};
const empMood=b=>{const e=ensureEmp(b);return e.length?Math.round(e.reduce((s,p)=>s+p.mood,0)/e.length):60};
const bizMgr=b=>b.mgr&&(b.emp||[]).find(p=>p.id===b.mgr)||null;
const wageBill=b=>(b.emp||[]).reduce((s,p)=>s+p.wage,0)+anonN(b)*BIZ[b.type].wage*cpi_();
const moodEm=m=>m>=70?'😄':m>=45?'🙂':m>=30?'😐':'😠';
const isCeo=b=>b.ceo!==false;
function bizAddStaff(b,n=1){ensureEmp(b);n=Math.min(Math.max(0,Math.floor(n)),staffRoom(b));b.staff+=n;while(b.emp.length<Math.min(b.staff,EMPMAX))b.emp.push(mkEmp(b));return n}
function bizRemove(b,p){b.emp=b.emp.filter(x=>x!==p);b.staff=Math.max(0,b.staff-1);if(b.mgr===p.id)b.mgr=null;if(anonN(b)>0&&b.emp.length<EMPMAX)b.emp.push(mkEmp(b))}
function bizCut(b){ensureEmp(b);if(anonN(b)>0){b.staff--;return}const w=b.emp.filter(p=>p.id!==b.mgr).sort((x,y)=>effSk(x)-effSk(y))[0];if(w){bizRemove(b,w);return w}}
function frInc(b){return b.frOn?Math.round((b.fr||0)*BIZ[b.type].rev0*cpi_()*.05*clamp(b.rep,20,100)/60):0}

/* ---------- het jaar van je bedrijf ---------- */
function bizYear(){
  for(const b of [...S.biz]){const T=BIZ[b.type];ensureEmp(b);bizV2(b);b.age++;
    const skill=(S.sk.zaken+S.sk[T.sk])/2,q=empQ(b),md=empMood(b),mg=bizMgr(b),fullJob=S.job&&!S.job.part;
    let g=QLL[qlOf(b)][4]+bizCyc(b)+T.g*(.4+R()*1.2)+(b.rep-50)/250+(skill-30)/300+(S.talent==='ondernemen'?.04:0)+gauss()*T.vol
      -(fullJob&&isCeo(b)?(mg?.01:.05):0)-(inJail()?(mg?.08:.25):0)+(b.age<=2?.04:0)+(q-50)/350+(md-50)/500+(mg?effSk(mg)/1000:0);
    const stale=b.age-(b.fresh||0);if(T.inv)g-=stale*.04;else if(stale>4)g-=(stale-4)*.015;b.g=g;
    const gm=b.mkt||0;b.mkt=0;const D0=b.dmax||demandCap(b);let fill=clamp(b.demand/Math.max(1,D0)*100,1,110)/100;const D=demandCap(b);const pm=b.mkFill||0;fill=Math.max(.03,fill-pm*.5);fill=fill*(1+g)*(1-(typeof warEcon==='function'?warEcon().biz:0));const mp=fill*gm;fill+=mp;b.mkFill=pm*.5+mp;fill=Math.min(1.05,Math.max(.03,fill));
    if(fill>=.9&&b.age>=3&&chance(.22)){fill*=.9;L(`${b.name}: er opent een nieuwe concurrent in de buurt. Een deel van je klanten probeert het uit.`,'bad')}b.demand=Math.max(800,Math.round(D*fill));b.dmax=D;b.fill=fill;const prev=b.rev;
    const cap=(1+b.staff)*T.cap*cpi_()*(.8+q/250)*(PRL[prOf(b)][5]||1);b.rev=Math.round(Math.min(b.demand,cap)*(b.price||1));b.util=b.demand/cap;
    const fi=frInc(b),own=isCeo(b)&&!inJail()?(b.sal||0):0;
    b.ohc=Math.round(b.rev*overheadPct(b));const Q_=QLL[qlOf(b)],P_=PRL[prOf(b)];const cogs=Math.round(b.rev/P_[2]*T.cogs*Q_[2]),opx=Math.round(b.rev*(OPEX[b.type]||.15)),rent=Math.round(T.fixed*cpi_()*rentSum(b)),wg=Math.round(wageBill(b));const cost=rent+wg+cogs+opx+own+b.ohc;const pre=Math.round(b.rev+fi-cost);b.vpb=vpb(pre);b.pre=pre;b.profit=pre-b.vpb;b.cash+=b.profit;
    b.pl={y:year(),rev:b.rev,fi,cogs,opx,rent,wg,own,oh:b.ohc,pre,vpb:b.vpb,net:b.profit};
    b.rep=clamp(b.rep+ri(-4,4)+(qlOf(b)===0&&prOf(b)===0?0:QLL[qlOf(b)][3])+(prOf(b)===2&&qlOf(b)<2?(qlOf(b)?-2:-6):0)+(b.profit>0?1:-2)+(b.util>1.15?-3:0)+Math.round((q-55)/20)+(md<35?-3:0));
    b.value=Math.max(0,Math.round((b.rev+fi*3)*T.mult*clamp(1+g,.5,2.2)*(b.pub?1.25:1)+Math.max(0,b.cash)));
    if(isCeo(b))sk('zaken',ri(1,3));b.down=prev&&b.rev<prev*.98?(b.down||0)+1:0;b.loss=b.profit<0?(b.loss||0)+1:0;
    // personeel: ervaring, humeur, pensioen, opstappen
    for(const p of [...b.emp]){p.yrs=(p.yrs||0)+1;p.esk=Math.min(99,p.esk+ri(0,3));const fair=T.wage*cpi_()*(.75+p.esk/200);
      p.mood=clamp(Math.round(p.mood+(62-p.mood)*.2+ri(-6,6)+(ETRAITS[p.tr]||[0,0])[1]-(p.wage<fair*.8?5:0)+(b.profit<0?-2:0)+(mg&&mg!==p?Math.round((effSk(mg)-50)/15):0)));
      if(pAge(p)>=67){bizRemove(b,p);L(`${p.first} ${p.last} gaat met pensioen na ${p.yrs} jaar bij ${b.name}.`);continue}
      if(p.mood<30&&chance(p.tr==='loyaal'?.1:.35)){bizRemove(b,p);bizAddStaff(b,1);const nw=b.emp[b.emp.length-1];L(`${p.first} (${p.fn.toLowerCase()}) neemt ontslag bij ${b.name}. Niet blij genoeg.${nw&&nw!==p?` ${nw.first} neemt de plek in.`:''}`,'bad')}}
    if(b.frOn){if(chance(clamp(b.rep/110,.1,.9)))b.fr=(b.fr||0)+ri(1,b.rep>75?4:2);if(b.rep<40&&b.fr&&chance(.4)){b.fr--;L(`Een franchisenemer van ${b.name} stopt ermee.`,'bad')}}
    if(b.down>=2)L(`${b.name}: de omzet daalt al ${b.down} jaar op rij. ${bizWhy(b)[0]||'Investeer in marketing, personeel of vernieuwing.'}`,'bad');
    L(`${b.name}: omzet ${fmt(b.rev)}${fi?` + ${fmt(fi)} franchise`:''}, ${b.profit>=0?'winst':'verlies'} ${fmt(Math.abs(b.profit))}.${b.util>1.1?' Je kunt de vraag niet aan, neem personeel aan.':''}`,b.profit>=0?'good':'bad');
    if(b.cash<0&&isCeo(b))Q.push({id:'s_bizcash',c:{bid:b.id}});
    if(b.pub&&b.eq<50&&b.loss>=2&&isCeo(b)&&!b.vote)Q.push({id:'bz_ceo',c:{bid:b.id}});
    else if(isCeo(b)&&S.biz.filter(isCeo).indexOf(b)<3)Q.push({id:'b_plan',c:{bid:b.id}});
  }}
function bizWhy(b){const T=BIZ[b.type],o=[];const stale=b.age-(b.fresh||0);
  if(S.job&&!S.job.part&&!bizMgr(b))o.push('Je werkt fulltime ernaast en er is geen manager: er gaat te weinig tijd in je bedrijf zitten.');
  if(econ()==='recessie')o.push('De economie zit in een recessie.');
  if((T.inv&&stale>=2)||stale>4)o.push('Je product of zaak raakt verouderd: tijd voor vernieuwing.');
  if(b.rep<45)o.push('Je reputatie is laag. Hard werken en marketing helpen.');
  if(b.emp&&b.emp.length&&empQ(b)<45)o.push('Je personeel is niet zo goed. Train ze of neem betere mensen aan.');
  if(b.emp&&b.emp.length&&empMood(b)<40)o.push('Je personeel is ontevreden. Dat merken klanten.');
  if((S.sk.zaken+S.sk[T.sk])/2<35)o.push('Je ondernemersvaardigheid is nog laag.');
  if(b.util>1.1)o.push('Je kunt de vraag niet aan: neem personeel aan.');
  if(!o.length)o.push('Investeer in marketing, personeel of vernieuwing.');return o}

/* ---------- overzicht en starten ---------- */
function sheetBizList(el){const s=sec(el,'Je bedrijven');if(!S.biz.length)empty(s,'Je hebt nog geen bedrijf.');
  for(const b of S.biz)row(s,{ic:BIZEM[b.type],t:b.name,s:`${BIZ[b.type].t}${b.loc>1?` · ${b.loc} ${ONLINE.includes(b.type)?'markten':'vestigingen'}`:''} · ${+(+b.eq).toFixed(2)}% van jou · waarde ${fmt(b.value)}`,on:()=>openSheet(b.name,el=>sheetBiz(el,b),true)});
  const n=sec(el,'Nieuw bedrijf');const a=ageY();
  row(n,{ic:'🚀',t:'Een bedrijf starten',s:a<18?'Vanaf 18 jaar':`${Object.keys(BIZ).length} soorten, van schoonmaakbedrijf tot app`,dis:a<18,on:()=>openSheet('Bedrijf starten',sheetStartBiz,true)});
  row(n,{ic:'🛒',t:'Een bedrijf overnemen',s:a<18?'Vanaf 18 jaar':'Bestaande bedrijven die te koop staan',dis:a<18,on:()=>openSheet('Bedrijf overnemen',sheetBuyBiz,true)})}
function bizReq(k){const T=BIZ[k],a=ageY();if(T.min&&a<T.min)return `Vanaf ${T.min} jaar`;if(T.vog&&typeof recentRec==='function'&&recentRec())return 'Je krijgt geen VOG met je strafblad';return ''}
function sheetStartBiz(el){for(const [g,ks] of BIZGRP){const s=sec(el,g);
  for(const k of ks){const T=BIZ[k];const no=bizReq(k);row(s,{ic:BIZEM[k],t:T.t,s:no||`Startkosten ${fmt(T.start*cpi_())}${T.s0?` · ${T.s0} personeel`:''}${T.inv?' · investeerders mogelijk':''}${T.vog?' · VOG nodig':''}`,dis:!!no,dots:true,on:()=>startPick(k)})}}}
function startPick(k){const T=BIZ[k];const def=pick(BIZPRE)+' '+pick(BIZSUF[k]);const price=Math.round(T.start*cpi_());const cap_=Math.max(20000,salary()*1.5+Math.max(0,netWorth())*.5)-S.loan;
  modal({title:T.t,em:BIZEM[k],cat:'Ondernemen',text:`Startkosten: ${fmt(price)}.${T.s0?` Je begint met ${T.s0} medewerker${T.s0>1?'s':''}.`:''} Hoe heet je bedrijf?`,html:`<input class="inp" id="bzn" maxlength="30" value="${he(def)}">`,choices:opts([
    {t:'Betalen met eigen geld',cls:'go',dis:S.money<price,on:()=>mk('eigen')},{t:'Zakelijke lening (6%)',dis:cap_<price,on:()=>mk('lening')}])});
  function mk(fund){const n=$('#bzn').value.trim()||def;closeModal();if(fund==='lening')S.loan+=price;else cash(-price);
    const b={id:uid(),type:k,name:n,buy:price,eq:100,demand:T.rev0*cpi_(),rev:0,staff:0,rep:50,age:0,cash:Math.round(price*.15),value:Math.round(price*.6),profit:0,mkt:0,loc:1,locs:[S.p.city||'je stad'],emp:[],sal:0};
    b.lo=[year()];b.v2=1;bizAddStaff(b,T.s0);S.biz.push(b);S.flags.ondernemer=1;L(`Je hebt ${n} opgericht, een ${T.t.toLowerCase()}.`,'good big');MS(`Richtte ${n} op`,2);hap(6);saveLife();render();sheetStack.pop();openSheet(b.name,el=>sheetBiz(el,b),true)}}
function startBiz(type,name,fund){const T=BIZ[type];const price=Math.round(T.start*cpi_());if(fund==='lening')S.loan+=price;else cash(-price);
  const b={id:uid(),type,name,buy:price,eq:100,demand:T.rev0*cpi_(),rev:0,staff:0,rep:50,age:0,cash:Math.round(price*.15),value:Math.round(price*.6),profit:0,mkt:0,loc:1,locs:[],emp:[],sal:0};
  b.lo=[year()];b.v2=1;bizAddStaff(b,T.s0);S.biz.push(b);S.flags.ondernemer=1;L(`Je hebt ${name} opgericht, een ${T.t.toLowerCase()}.`,'good big');MS(`Richtte ${name} op`,2);return b}
// te koop: elk jaar een nieuwe lijst
function bizMarket(){if(S.bizMkt&&S.bizMkt.y===year())return S.bizMkt.l;const l=[];const ks=Object.keys(BIZ).filter(k=>!bizReq(k));
  for(let i=0;i<5;i++){const k=pick(ks),T=BIZ[k];const age=ri(2,25),rep=ri(30,88);const dem=Math.round(T.rev0*cpi_()*(.6+R()*2.4)*(.7+rep/150));const staff=Math.max(T.s0,Math.round(dem/(T.cap*cpi_()))-1+ri(0,1));
    const loc=ONLINE.includes(k)?1:dem>T.rev0*cpi_()*2.2&&chance(.5)?ri(2,3):1;const cashv=Math.round(dem*R()*.1);const rev=Math.round(Math.min(dem,(1+staff)*T.cap*cpi_()));const profit=Math.round(rev*(1-T.cogs)-T.fixed*cpi_()*(1+(loc-1)*.8)-staff*T.wage*cpi_());
    const price=Math.max(Math.round(T.start*cpi_()*.5),Math.round((rev*T.mult*(.7+R()*.6)+cashv)/1000)*1000);
    const why=profit<0?pick(['De eigenaar is het zat','Draait verlies, kans voor een slimme koper','Faillissement dreigt']):pick(['De eigenaar gaat met pensioen','De eigenaar emigreert','Erfgenamen willen verkopen','De eigenaar begint iets nieuws','Familiebedrijf zonder opvolger']);
    l.push({id:uid(),k,name:pick(BIZPRE)+' '+pick(BIZSUF[k]),age,rep,dem,staff,loc,cash:cashv,rev,profit,price,why})}
  S.bizMkt={y:year(),l};return l}
function sheetBuyBiz(el){const l=bizMarket().filter(x=>!x.sold);const s=sec(el,'Te koop dit jaar');if(!l.length)empty(s,'Alles is verkocht. Volgend jaar komt er een nieuwe lijst.');
  for(const x of l){const T=BIZ[x.k];row(s,{ic:BIZEM[x.k],t:x.name,s:`${T.t} · ${x.age} jaar oud · omzet ${fmt(x.rev)} · ${x.profit>=0?'winst':'verlies'} ${fmt(Math.abs(x.profit))} · ${x.staff} personeel · vraagprijs ${fmt(x.price)}`,dots:true,on:()=>buyBiz(x)})}
  card(el,`<span class="muted">Elk jaar komen er nieuwe bedrijven op de markt. Een overname is sneller dan zelf beginnen: je krijgt meteen klanten, personeel en een naam.</span>`)}
function buyBiz(x){const T=BIZ[x.k];const loanCap=Math.max(0,Math.round(salary()*2+Math.max(0,netWorth())*.6-S.loan));const own=Math.round(x.price*.3);
  modal({title:x.name,em:BIZEM[x.k],cat:'Overname',html:pkv([['Soort',T.t],['Leeftijd',`${x.age} jaar`],['Omzet',fmt(x.rev)],[x.profit>=0?'Winst':'Verlies',fmt(Math.abs(x.profit))],['Personeel',x.staff],...(x.loc>1?[['Vestigingen',x.loc]]:[]),['Reputatie',x.rep+'%'],['Waarom te koop',x.why],['Vraagprijs',`<b>${fmt(x.price)}</b>`]]),choices:opts([
    {t:`Kopen met eigen geld`,cls:'go',dis:S.money<x.price,on:()=>go(x.price,0)},
    {t:`Bank financiert 70% (jij legt ${fmt(own)} in)`,dis:S.money<own||loanCap<x.price-own,on:()=>go(own,x.price-own)},
    {t:'Onderhandelen',dis:!!x.neg,on:()=>{x.neg=1;closeModal();if(chance(.25+S.sk.zaken/250)){x.price=Math.round(x.price*(.8+R()*.12)/1000)*1000;toast(`De verkoper zakt naar ${fmt(x.price)}`)}else if(chance(.3)){x.sold=1;toast('De verkoper is beledigd en verkoopt aan een ander')}else toast('De verkoper houdt voet bij stuk');refreshSheet()}}])});
  function go(pay,loan){closeModal();cash(-pay);S.loan+=loan;x.sold=1;
    const b={id:uid(),type:x.k,name:x.name,buy:x.price,eq:100,demand:x.dem,rev:x.rev,staff:0,rep:x.rep,age:x.age,cash:x.cash,value:x.price,profit:x.profit,mkt:0,loc:x.loc,locs:[],emp:[],sal:0,fresh:x.age-ri(0,4)};
    b.lo=Array(x.loc).fill(year()-5);b.v2=1;b.demand=Math.min(b.demand,demandCap(b));bizAddStaff(b,x.staff);for(const p of b.emp){p.yrs=ri(0,Math.min(x.age,15));p.mood=clamp(p.mood-ri(0,15))}
    S.biz.push(b);S.flags.ondernemer=1;L(`Je hebt ${x.name} overgenomen voor ${fmt(x.price)}.`,'good big');MS(`Nam ${x.name} over`,2);hap(5);saveLife();render();sheetStack.pop();openSheet(b.name,el=>sheetBiz(el,b),true)}}

/* ---------- je bedrijf ---------- */
function sheetBiz(el,b){if(!S.biz.includes(b)){empty(el,'Dit bedrijf bestaat niet meer.');return}const T=BIZ[b.type];ensureEmp(b);bizV2(b);const ceo=isCeo(b),on=ONLINE.includes(b.type);
  card(el,`<h3>${BIZEM[b.type]} ${he(b.name)}</h3><span class="muted">${T.t} · ${b.age} jaar oud · jij bezit ${+(+b.eq).toFixed(2)}% · ${ceo?'directeur-eigenaar':'aandeelhouder'}${b.pub?' · beursgenoteerd':''}</span>${kv([['Omzet vorig jaar',fmt(b.rev)],...(b.vpb?[['Vennootschapsbelasting',fmt(b.vpb)]]:[]),...(b.ohc?[['Hoofdkantoor en regiomanagers',fmt(b.ohc)]]:[]),['Winst vorig jaar',fmt(b.profit)],...(b.dmax?[['Markt benut',Math.round(Math.min(1,b.demand/Math.max(1,b.dmax))*100)+'%']]:[]),['In kas',fmt(b.cash)],['Opgericht voor',boughtFor(b)],['Waarde',fmt(b.value)],...(b.loc>1?[[on?'Markten':'Vestigingen',`${b.loc}${b.locs&&b.locs.length?' · '+he(b.locs.slice(-3).join(', '))+(b.locs.length>3?' …':''):''}`],['Omzet per '+(on?'markt':'vestiging'),fmt(b.rev/b.loc)]]:[]),...(b.frOn?[['Franchisenemers',`${b.fr||0} · ${fmt(frInc(b))} per jaar`]]:[]),['Personeel',`${b.staff} · kwaliteit ${empQ(b)}% · ${moodEm(empMood(b))}`],...(ceo?[['Jouw salaris',b.sal?fmt(b.sal)+' per jaar':'geen']]:[]),['Capaciteit benut',b.rev?Math.round(Math.min(1.5,b.util||0)*100)+'%':'nog onbekend']])}<div class="stat"><span>Reputatie</span><span></span><span class="v">${Math.round(b.rep)}%</span>${bar(b.rep)}</div>${b.age?(b.down>=2?`<div class="bizwarn"><b>⚠️ Omzet daalt al ${b.down} jaar op rij</b>${bizWhy(b).map(x=>`<span>${he(x)}</span>`).join('')}</div>`:b.down===1?`<div class="bizwarn soft"><b>📉 Omzet daalde vorig jaar</b><span>${he(bizWhy(b)[0])}</span></div>`:(b.g||0)>.03?`<div class="bizok">📈 De omzet groeit</div>`:''):''}`);
  const kas=k=>{if(b.cash>=k)return true;toast(`Te weinig in de bedrijfskas (${fmt(b.cash)}). Leg eerst geld in.`);return false};const kasS=k=>b.cash<k?` · te weinig in kas`:'';
  if(ceo){const d=sec(el,'Jij als directeur');
    row(d,{ic:'💼',t:'Je eigen salaris',s:b.sal?`${fmt(b.sal)} per jaar · telt als je inkomen`:'Je betaalt jezelf nu niets uit',dots:true,on:()=>salPick(b)});
    row(d,{ic:'💪',t:'Zelf hard werken',s:'Beter voor je bedrijf, zwaar voor jou',on:()=>doAct('Hard werken',()=>{const m=use('bw'+b.id);sk('zaken',3*m);sk(T.sk,2*m);b.rep=clamp(b.rep+3*m);b.mkt+=.03*m;return pickF('bw',['Je maakt lange dagen.','Je staat zelf achter de toonbank. Klanten vinden het leuk de baas te zien.','Je werkt tot diep in de nacht aan plannen.','Je doet alles zelf even. Het personeel kijkt goedkeurend toe.'])},true,'💪')});
    const ren=Math.round(Math.max(5000,b.rev*.12)*cpi_()/100)*100,stale=b.age-(b.fresh||0);
    row(d,{ic:'✨',t:'Vernieuwen',s:S.acts['ren'+b.id]?'Dit jaar al gedaan':`${fmt(ren)} · ${{restaurant:'nieuwe kaart en verbouwing',foodtruck:'nieuw menu',saas:'nieuwe versie van je software',app:'grote update van je app',kleding:'nieuwe collectie',platenlabel:'nieuwe artiesten tekenen',sportschool:'nieuwe apparaten',nachtclub:'nieuw geluid en licht',escape:'een nieuwe kamer'}[b.type]||'je zaak moderniseren'}${stale>=3?' · hard nodig':''}${kasS(ren)}`,dis:!!S.acts['ren'+b.id]||b.cash<ren,dots:true,on:()=>doAct('Vernieuwen',()=>{if(!kas(ren))return null;S.acts['ren'+b.id]=1;b.cash-=ren;b.fresh=b.age;b.mkt+=.05;b.rep=clamp(b.rep+5);return 'Je zaak is weer helemaal van deze tijd. Klanten merken het.'},true,'✨')});
    {const mk=Math.max(2000,Math.round(b.rev*.05));row(d,{ic:'📣',t:'Marketingcampagne',s:`Kost ${fmt(mk)} · meer vraag${kasS(mk)}`,dis:b.cash<mk,on:()=>doAct('Marketing',()=>{const k=mk;if(!kas(k))return null;b.cash-=k;const m=use('mkt'+b.id);b.mkt+=(.06+R()*.12)*m;b.rep=clamp(b.rep+3);return pickF('mkt',['De campagne loopt. Volgend jaar merk je het effect.','Je hangt posters op in de hele stad.','Een influencer noemt je zaak in een filmpje.','Je adverteert online. De eerste klikken komen binnen.','Je deelt kortingsbonnen uit op de markt.'])},true,'📣')})}
    const st=sec(el,'Koers');const P_=PRL[prOf(b)],Q_=QLL[qlOf(b)];
    row(st,{ic:P_[1],t:`Prijsniveau: ${P_[0].toLowerCase()}`,s:P_[4],dots:true,on:()=>modal({title:'Prijsniveau',em:'🏷️',cat:b.name,text:'Goedkoop trekt meer klanten, premium levert meer per klant op. Premium werkt alleen met goede kwaliteit.',choices:opts(PRL.map((x,i)=>({t:`${x[1]} ${x[0]}`,s:x[4],cls:prOf(b)===i?'go':'',on:()=>{closeModal();b.pr=i;b.price=x[2];toast(`Prijsniveau: ${x[0].toLowerCase()}`);refreshSheet();saveLife()}})))})});
    row(st,{ic:Q_[1],t:`Kwaliteit: ${Q_[0].toLowerCase()}`,s:Q_[5],dots:true,on:()=>modal({title:'Kwaliteit',em:'⭐',cat:b.name,text:'Betere inkoop kost meer, maar je reputatie groeit en klanten komen terug.',choices:opts(QLL.map((x,i)=>({t:`${x[1]} ${x[0]}`,s:`${x[5]} · inkoopkosten ${x[2]===1?'normaal':x[2]<1?'-20%':'+25%'}`,cls:qlOf(b)===i?'go':'',on:()=>{closeModal();b.ql=i;toast(`Kwaliteit: ${x[0].toLowerCase()}`);refreshSheet();saveLife()}})))})});
    if(!on){bizLo(b);const cnt={A:0,B:0,C:0};for(const t of b.la)cnt[t]++;row(st,{ic:'📍',t:'Je locaties',s:Object.entries(cnt).filter(([,v])=>v).map(([k,v])=>`${v}× ${LOCT[k][0]}`).join(' · '),dots:true,on:()=>relocMenu(b)})}
    if(b.pl)row(st,{ic:'📊',t:'Jaaroverzicht',s:`Winst-en-verliesrekening ${b.pl.y}`,dots:true,on:()=>plModal(b)});
    const ps=sec(el,'Personeel');const mg=bizMgr(b);
    row(ps,{ic:'👥',t:`Je personeel (${b.staff})`,s:b.staff?`${b.emp.length>=EMPMAX&&anonN(b)?`${EMPMAX} bij naam + ${anonN(b)} anderen`:`${b.emp.length} bij naam`} · loonkosten ${fmt(wageBill(b))} per jaar${mg?` · manager: ${mg.first}`:''}`:'Nog niemand in dienst',on:()=>openSheet('Personeel',el=>sheetStaff(el,b),true)});
    const g=sec(el,'Groeien');
    const lc=locCost(b,b.loc),lok=b.age>=1&&b.rep>=55;
    if(b.loc>1)row(g,{ic:'🏚️',t:on?'Markten opgeven':'Vestigingen sluiten',s:`Slecht lopende ${on?'markten':'vestigingen'} afstoten · je hebt er ${b.loc.toLocaleString('nl-NL')}`,dots:true,on:()=>closeLocs(b)});
    row(g,{ic:on?'🌍':'🏬',t:on?'Naar een nieuw land':'Nieuwe vestiging openen',s:!lok?`Kan vanaf 1 jaar oud en 55% reputatie`:!locLeft(b)?(on?'Je zit al in alle landen':`Je hebt het maximum van ${LOCMAX} vestigingen`):`Vanaf ${fmt(lc)} · een of meerdere tegelijk${kasS(lc)}`,dis:!lok||b.cash<lc||!locLeft(b),dots:true,on:()=>newLoc(b)});
    if(FRANCH.includes(b.type)&&!b.frOn){const fok=b.loc>=3&&b.rep>=60;row(g,{ic:'🤝',t:'Franchise starten',s:fok?`${fmt(25000*cpi_())} · anderen openen een zaak onder jouw naam en betalen jou royalty`:'Kan vanaf 3 vestigingen en 60% reputatie',dis:!fok||b.cash<25000*cpi_(),dots:true,on:()=>startFranchise(b)})}
    if(!b.pub){const iok=b.value>=20e6*cpi_()&&b.age>=5&&b.eq>=40;row(g,{ic:'🔔',t:'Naar de beurs',s:iok?'Verkoop nieuwe aandelen aan beleggers':`Kan vanaf ${fmt(20e6*cpi_())} waarde en 5 jaar oud`,dis:!iok,dots:true,on:()=>ipo(b)})}}
  else card(el,`<b>🗳️ Je bent weggestemd als directeur.</b><br><span class="muted">Je bent nog wel aandeelhouder. Je kunt je aandelen houden of verkopen.</span>`);
  const m=sec(el,'Geld');
  if(ceo)row(m,{ic:'💶',t:'Winst uitkeren',s:'25% belasting',dis:b.cash<=0,dots:true,on:()=>amountModal('Winst uitkeren',b.cash,v=>doAct('Winst uitkeren',()=>{b.cash-=v;const get=Math.round(v*b.eq/100*.75);cash(get);return `Je ontvangt ${fmt(get)}.`},true,'💶'))});
  if(ceo)row(m,{ic:'🏦',t:'Geld inleggen',dis:S.money<=0,dots:true,on:()=>amountModal('Geld inleggen',S.money,v=>doAct('Geld inleggen',()=>{cash(-v);b.cash+=v;b.buy=(b.buy??0)+v;return `${fmt(v)} naar ${b.name}.`},true,'🏦'))});
  if(ceo&&T.inv&&!b.pub)row(m,{ic:'🤝',t:'Investeerders zoeken',dis:!!S.acts['inv'+b.id]||b.eq<=20,dots:true,on:()=>mgMemory('Pitch voor investeerders','Onthoud je pitch en vertel hem in de juiste volgorde.',5,(ok)=>{PREPAID=0;S.acts['inv'+b.id]=1;if(chance((ok?.5:.12)+b.rep/300+S.sk.zaken/400)){closeSheet();Q.push({id:'investeerder',c:{bid:b.id}});processQ()}else{toast(ok?'Goede pitch, maar niemand bijt toe':'Je pitch overtuigt niemand');refreshSheet();render()}})});
  if(b.pub)row(m,{ic:'📈',t:'Aandelen verkopen',s:`Je hebt ${+(+b.eq).toFixed(2)}% · beurswaarde ${fmt(b.value)}`,dis:b.eq<=1,dots:true,on:()=>sellShares(b)});
  const x=sec(el,'');
  if(!b.pub)row(x,{ic:'🏷️',t:'Bedrijf verkopen',dis:!!S.acts['sell'+b.id],dots:true,on:()=>{S.acts['sell'+b.id]=1;const offer=Math.round(b.value*(.7+R()*.6));if(offer<1000){toast('Niemand wil je bedrijf kopen');return refreshSheet()}
    modal({title:'Een koper!',em:'🏷️',cat:'Ondernemen',text:`Een koper biedt ${fmt(offer)} voor ${b.name}. Jouw deel is ${fmt(offer*b.eq/100)}.${b.buy!=null?` Je richtte het op voor ${fmt(b.buy)}.`:''}`,choices:[{t:'Verkopen',cls:'go',on:()=>{closeModal();sellBiz(b,offer);hap(10);backSheet();render();saveLife();toast('Verkocht!')}},{t:'Niet verkopen',cls:'ghost',on:()=>{closeModal();refreshSheet()}}]})}});
  if(ceo&&!b.pub)row(x,{ic:'🔒',t:'Bedrijf sluiten',dots:true,on:()=>ask('Bedrijf sluiten?',`${b.name} stopt. Wat in kas zit (${fmt(Math.max(0,b.cash))}) gaat naar jou. Je personeel verliest zijn baan.`,'Sluiten',()=>{cash(Math.max(0,b.cash)*b.eq/100);S.biz=S.biz.filter(y=>y!==b);L(`Je hebt ${b.name} gesloten.`);MS(`Sloot ${b.name}`,1);render();saveLife();backSheet()})})}
function salPick(b){const T=BIZ[b.type];const w=T.wage*cpi_();const r=x=>Math.round(x/1000)*1000;const lv=[['Geen salaris',0,'Alles blijft in het bedrijf'],['Bescheiden',r(w*.7),'Minder dan je personeel'],['Marktconform',r(w*1.4),'Wat een directeur normaal verdient'],['Royaal',r(Math.max(w*3,b.rev*.12)),'Lekker, maar je bedrijf voelt het']];
  modal({title:'Je eigen salaris',em:'💼',cat:b.name,text:`Wat betaal je jezelf per jaar? Het salaris komt uit je bedrijf en telt als je inkomen (daar betaal je belasting over).${b.sal?` Nu: ${fmt(b.sal)}.`:''}`,choices:opts([...lv.map(([t,v,d])=>({t:`${t}${v?' · '+fmt(v):''}`,s:d,cls:b.sal===v?'go':'',on:()=>{closeModal();b.sal=v;toast(v?`Je salaris is nu ${fmt(v)} per jaar`:'Je betaalt jezelf niets meer uit');refreshSheet();render();saveLife()}})),
    {t:'Eigen bedrag',on:()=>{closeModal();amountModal('Jaarsalaris',Math.max(r(w*5),r(b.rev*.4)),v=>{b.sal=v;toast(`Je salaris is nu ${fmt(v)} per jaar`);refreshSheet();render();saveLife()})}}])})}
function locPlan(b,lt){lt=lt||'B';const L_=LOCT[lt];const T=BIZ[b.type];ensureEmp(b);bizV2(b);const fill=Math.min(1,b.fill||(b.demand/Math.max(1,demandCap(b))));const pk=peakOf(b)*canni(b,b.loc)*fill*L_[2];
  const add=Math.round(pk*ramp(0)),full=Math.round(pk);const capPer=T.cap*cpi_()*(.8+empQ(b)/250);const n=Math.min(STAFFMAX,Math.max(T.s0,Math.ceil(full/capPer)));const n0=Math.max(T.s0,Math.ceil(add/capPer));
  const fixed=Math.round(T.fixed*cpi_()*L_[3]);const wages=Math.round(n*T.wage*cpi_());const oh=overheadPct(Object.assign({},b,{loc:b.loc+1}));
  const P_=PRL[prOf(b)],Q_=QLL[qlOf(b)];const res=(rv,st)=>Math.round(rv*P_[2]*(1-(OPEX[b.type]||.15)-oh)-rv*T.cogs*Q_[2]-fixed-st*T.wage*cpi_());const p0=res(add,n0),p3=res(full,n);const aft=x=>x>0?x-vpb(x):x;
  return {add,full,n:n0,n3:n,fixed,wages,profit:aft(p0),profit3:aft(p3),lt}}
const ABROAD=['Antwerpen','Gent','Brussel','Düsseldorf','Keulen','Berlijn','Hamburg','München','Parijs','Lyon','Londen','Manchester','Barcelona','Madrid','Milaan','Rome','Wenen','Zürich','Kopenhagen','Stockholm','Dublin','Lissabon','Praag','New York','Dubai'];
let LT_=null;const locBase=b=>(OPEN[b.type]||BIZ[b.type].start)*cpi_()*(LT_?LOCT[LT_][4]:1);
const locCost=(b,l)=>Math.round(locBase(b)*(1+Math.min(l-1,20)*.15)/1000)*1000;
const LOCMAX=2500;const locLeft=b=>ONLINE.includes(b.type)?BIZLAND.filter(x=>!b.locs.includes(x)).length:Math.max(0,LOCMAX-b.loc);
function locNames(b,n){const on=ONLINE.includes(b.type);const out=[];const used=new Set(b.locs);
  for(let i=0;i<n;i++){let w;if(on)w=BIZLAND.find(x=>!used.has(x));else{const nl=NLCITY.filter(x=>!used.has(x));const ab=ABROAD.filter(x=>!used.has(x));w=nl.length?pick(nl):ab.length?ab[0]:null}if(!w)break;used.add(w);out.push(w)}return out}
// totale kosten van n nieuwe vestigingen (elke volgende 15% van de basis duurder)
