E('be_diefstal',{c:bzOk,cd:4,w:.7,t:'Geld weg uit de kassa',ctx:empCtx(),x:c=>{const b=B(c);const thief=b.emp.find(p=>p.tr==='onbetrouwbaar')||(chance(.5)?EP(c):null);c.g=thief?thief.id:null;c.k=Math.round(ri(1,12)*1000*cpi_());return `Er is ${fmt(c.k)} verdwenen bij ${b.name}. Een collega wijst naar ${EP(c).first}.`},ch:[
 ['👋 Op staande voet ontslaan',c=>{const p=EP(c),b=B(c);bizRemove(b,p);if(c.g===p.id)return `${p.first} bekent. Weg ermee.`;for(const x of b.emp)x.mood=clamp(x.mood-8);return `Later blijkt ${p.first} onschuldig. Het team vertrouwt je minder.`}],
 ['🕵️ Eerst uitzoeken',c=>{const b=B(c);const t=b.emp.find(x=>x.id===c.g);if(t){bizRemove(b,t);b.cash+=Math.round(c.k*.5);return `Op de camerabeelden zie je het: het was ${t.first}. Ontslagen, en je krijgt de helft terug.`}return 'Het geld blijkt verkeerd geboekt. Niemand heeft iets gestolen. Gelukkig heb je niets overhaast gedaan.'}],
 ['🤷 Laten rusten',c=>{const b=B(c);bzPay(b,0);return 'Je laat het zitten. Het blijft knagen.'}]]});
E('be_ruzie',{c:bzOk,cd:3,w:.7,t:'Ruzie op de werkvloer',ctx:()=>{const bs=S.biz.filter(b=>isCeo(b)&&(ensureEmp(b),b.emp.length>=2));if(!bs.length)return null;const b=pick(bs);const [x,y]=b.emp.slice().sort(()=>R()-.5).slice(0,2);return {bid:b.id,id:x.id,o:y.id}},x:c=>{const b=B(c);const y=b.emp.find(p=>p.id===c.o);return `${EP(c).first} en ${y?y.first:'een collega'} hebben flinke ruzie. ${pick(['Over de planning.','Over wie het meeste werk doet.','Over een fout die niemand wil toegeven.','Het gaat over iets privés.'])} Het hele team merkt het.`},ch:[
 ['☝️ Kant kiezen voor de eerste',c=>{const b=B(c),p=EP(c),y=b.emp.find(q=>q.id===c.o);p.mood=clamp(p.mood+8);if(y){y.mood=clamp(y.mood-20);y.rel=clamp(y.rel-15)}return `${p.first} is opgelucht. ${y?y.first:'De ander'} is woest.`}],
 ['✌️ Kant kiezen voor de tweede',c=>{const b=B(c),p=EP(c),y=b.emp.find(q=>q.id===c.o);p.mood=clamp(p.mood-20);p.rel=clamp(p.rel-15);if(y)y.mood=clamp(y.mood+8);return `${y?y.first:'De ander'} krijgt gelijk. ${p.first} is woest.`}],
 ['🤝 Samen om tafel',c=>{const b=B(c),p=EP(c),y=b.emp.find(q=>q.id===c.o);if(chance(.6)){p.mood=clamp(p.mood+4);if(y)y.mood=clamp(y.mood+4);sk('sociaal',2);return 'Na een goed gesprek geven ze elkaar een hand.'}return 'Het gesprek loopt uit op nog meer geschreeuw.'}]]});
E('be_weg',{c:bzOk,cd:3,w:.7,t:'Een aanbod van elders',ctx:empCtx(p=>effSk(p)>=65),x:c=>`${EP(c).first}, een van je beste mensen, heeft een aanbod gekregen van een ander bedrijf. 30% meer salaris.`,ch:[
 ['💶 Tegenbod: 20% erbij',c=>{const p=EP(c);if(chance(.7)){p.wage=Math.round(p.wage*1.2/100)*100;p.mood=clamp(p.mood+10);return `${p.first} blijft.`}bizRemove(B(c),p);return `${p.first} bedankt je, maar vertrekt toch.`}],
 ['⭐ Manager maken',c=>{const p=EP(c),b=B(c);const o=bizMgr(b);if(o)o.mood=clamp(o.mood-15);b.mgr=p.id;p.wage=Math.round(p.wage*1.25/100)*100;p.mood=clamp(p.mood+15);return `${p.first} blijft als nieuwe manager.`}],
 ['👋 Laten gaan',c=>{const p=EP(c);bizRemove(B(c),p);return `Je wenst ${p.first} succes.`}]]});
E('be_idee',{c:bzOk,cd:3,w:.8,t:'Een idee',ctx:empCtx(p=>p.mood>=50),x:c=>`${EP(c).first} heeft een idee voor ${B(c).name}: ${pick(['een nieuw product','een slimmere werkwijze','een samenwerking met een bekend merk','een abonnement voor vaste klanten'])}.`,ch:[
 ['👍 Proberen',c=>{const p=EP(c),b=B(c);const k=Math.max(1000,Math.round(b.rev*.02));bzPay(b,k);p.mood=clamp(p.mood+8);if(chance(.35+effSk(p)/250)){b.demand*=1.15;b.rep=clamp(b.rep+4);return `Het werkt! ${p.first} is de held van de week.`}return `Het slaat niet aan. Het kostte ${fmt(k)}, maar ${p.first} waardeert het vertrouwen.`}],
 ['👎 Nee, bedankt',c=>{const p=EP(c);p.mood=clamp(p.mood-6);return `${p.first} had er meer van verwacht.`}]]});
E('bz_vestiging',{c:()=>bzOk()&&S.biz.some(b=>isCeo(b)&&b.loc>=3&&!ONLINE.includes(b.type)),cd:4,t:'Misstand in een vestiging',ctx:bzCtx(b=>b.loc>=3&&!ONLINE.includes(b.type)),x:c=>{const b=B(c);c.city=pick(b.locs&&b.locs.length?b.locs:NLCITY);return `In je vestiging in ${c.city} ${pick(['blijkt de keuken vol muizen te zitten','werden klanten onbeschoft behandeld en dat staat online','is een medewerker onderbetaald, en een journalist pikt het op','ging iets mis met de hygiëne, en een klant werd ziek'])}. Het gaat over je hele bedrijf.`},ch:[
 ['🔒 Die vestiging tijdelijk sluiten en alles laten checken',c=>{const b=B(c);const k=Math.round(BIZ[b.type].fixed*cpi_()*.5);bzPay(b,k);b.rep=clamp(b.rep-3);return `Je sluit de vestiging in ${c.city} een maand (${fmt(k)}). Mensen waarderen dat je het serieus neemt.`}],
 ['🙏 Excuses en een onafhankelijk onderzoek',c=>{const b=B(c);const k=Math.round(ri(10,40)*1000*cpi_());bzPay(b,k);b.rep=clamp(b.rep-6);return `Het onderzoek kost ${fmt(k)}. De schade blijft beperkt.`}],
 ['🙅 Ontkennen',c=>{const b=B(c);if(chance(.35)){b.rep=clamp(b.rep-2);return 'Het waait over. Dit keer.'}b.rep=clamp(b.rep-15);b.demand*=.88;return 'Er komt meer naar buiten. Je hele bedrijf ligt onder vuur.'}]]});
E('bz_acm',{c:()=>bzOk()&&S.biz.some(b=>isCeo(b)&&(b.loc>=50||b.rev>=50e6*cpi_())),cd:6,w:.7,t:'De toezichthouder',ctx:bzCtx(b=>b.loc>=50||b.rev>=50e6*cpi_()),x:c=>{const b=B(c);c.f=Math.round(b.rev*ri(1,4)/100);return `De ACM onderzoekt ${b.name}: ${pick(['jullie zouden prijsafspraken hebben gemaakt met concurrenten','jullie zouden je machtspositie misbruiken','leveranciers klagen over oneerlijke contracten'])}. Een boete kan oplopen tot ${fmt(c.f*2)}.`},ch:[
 ['🤝 Meewerken en schikken',c=>{const b=B(c);bzPay(b,c.f);b.rep=clamp(b.rep-4);return `Je schikt voor ${fmt(c.f)}. Het blijft netjes.`}],
 ['⚖️ Een topadvocatenkantoor',c=>{const b=B(c);const k=Math.round(c.f*.15);bzPay(b,k);if(chance(.45+S.sk.zaken/400)){return `Na twee jaar procederen win je. Kosten advocaten: ${fmt(k)}.`}bzPay(b,c.f*2);b.rep=clamp(b.rep-8);return `Je verliest. Boete: ${fmt(c.f*2)}, plus ${fmt(k)} voor de advocaten.`}]]});
E('bz_claim',{c:()=>bzOk()&&S.biz.some(b=>isCeo(b)&&b.rev>=10e6*cpi_()),cd:5,w:.6,t:'Een massaclaim',ctx:bzCtx(b=>b.rev>=10e6*cpi_()),x:c=>{const b=B(c);c.f=Math.round(b.rev*ri(2,8)/100);return `Een stichting start een massaclaim tegen ${b.name} namens ${nfS(ri(2,40)*1000)} klanten. Ze eisen ${fmt(c.f)}.`},ch:[
 ['🤝 Schikken voor de helft',c=>{const b=B(c);bzPay(b,Math.round(c.f/2));return `Je betaalt ${fmt(c.f/2)} en de zaak is van tafel.`}],
 ['⚖️ Tot het eind procederen',c=>{const b=B(c);const k=Math.round(c.f*.08);bzPay(b,k);if(chance(.5))return `De rechter wijst de claim af. Advocaatkosten: ${fmt(k)}.`;bzPay(b,c.f);b.rep=clamp(b.rep-6);return `De claim wordt toegewezen: ${fmt(c.f)} plus ${fmt(k)} advocaatkosten.`}]]});
